usage() {
  printf '%s\n' \
    "Usage:" \
    "  NODE1_RDMA_IP=<ip1> ... NODE15_RDMA_IP=<ip15> bash scripts/arm_roce_16node.sh <mode> [options]" \
    "" \
    "Modes:" \
    "  check    Check toolchain, headers, RDMA, routes, dataset, and shared path." \
    "  build    Run check, configure CMake for 16 nodes, and compile." \
    "  index    Run the distributed index build across 16 nodes." \
    "  search   Search the completed index across 16 nodes." \
    "" \
    "Important options:" \
    "  --node0-rdma-ip IP .. --node15-rdma-ip IP  RoCE IPs for the 16 nodes." \
    "  --leader-ip IP       Memcached address (usually node 0)." \
    "  --dataset-dir PATH   Default: ${DATASET_DIR}" \
    "  --base-file PATH     Override automatic base bin discovery." \
    "  --query-file PATH    Override automatic query bin discovery." \
    "  --gt-file PATH       Override automatic GT bin discovery." \
    "  --output-dir PATH    Shared index directory (must be visible on all nodes)." \
    "  --build-dir PATH     Per-host CMake build directory." \
    "  --threads N          Set both index and RDMA threads (legacy)." \
    "  --index-threads N    DiskANN/OpenMP build threads. Default: 8" \
    "  --rdma-threads N     CoTra/RDMA worker threads. Default: 8" \
    "  --max-threads N      Compile-time thread array size cap. Default: 128" \
    "  --max-degree R       Graph max out-degree (M/R). 8node default: 48" \
    "  --build-l L          Build queue size / efC. 8node default: 500" \
    "  --search-dram-gb GB  Search-stage DRAM cap / -B.  Default: 16" \
    "  --build-dram-gb GB   Build-stage DRAM cap / -M.   Default: 64" \
    "  --query-size N       Search query count. Default: auto from file header" \
    "  --res-knn K          Recall@K target. Default: 10" \
    "  --build-jobs N       Parallel compile jobs. Default: 24" \
    "  --gid-index N        Override automatic RoCE GID selection." \
    "  --deps-dir PATH      Shared dir with include/lib64 copied from a healthy" \
    "                       node (e.g. shared_deps: include/ + lib64/ subdirs)." \
    "  --help               Show this message." \
    "" \
    "Start node 0 first on every mode, then nodes 1..15."
}

die() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 1
}

warn() {
  printf 'WARN: %s\n' "$*" >&2
}

note() {
  printf '\n=== %s ===\n' "$*"
}

is_positive_integer() {
  [[ $1 =~ ^[1-9][0-9]*$ ]]
}

is_nonnegative_integer() {
  [[ $1 =~ ^[0-9]+$ ]]
}

is_ipv4() {
  local ip=$1
  local a b c d extra
  IFS=. read -r a b c d extra <<<"${ip}"
  [[ -z ${extra:-} && -n ${a:-} && -n ${b:-} && -n ${c:-} && -n ${d:-} ]] ||
    return 1
  for part in "$a" "$b" "$c" "$d"; do
    [[ $part =~ ^[0-9]+$ ]] || return 1
    ((10#$part >= 0 && 10#$part <= 255)) || return 1
  done
}

